"""Writes the TypeScript form of the contract, so the Python and web sides cannot drift."""

import types
from dataclasses import fields, is_dataclass
from typing import Any, Literal, Union, get_args, get_origin, get_type_hints

from saltmarket.web import contract as c

HEADER = """\
// Generated by scripts/export_contract.py from src/saltmarket/web/contract.py.
// Do not edit by hand: run the script again after changing the Python dataclasses.
"""

SESSION_INTERFACE = """\
export type Unsubscribe = () => void;

/** The runtime behind the website. Task 5 implements it on top of the Python GameSession. */
export interface GameSession {
  /** Loads the runtime once, then plays to the first human decision. */
  start(config: SessionConfig): Promise<void>;
  /** The pending human decision, else null. */
  current(): Decision | null;
  /** Rejects illegal ids. Otherwise plays on to the next human decision or the end. */
  submit(action: number): Promise<SubmitResult>;
  /** The append-only event log, from index sinceIndex. */
  events(sinceIndex?: number): GameEvent[];
  onEvent(callback: (event: GameEvent) => void): Unsubscribe;
  onDecision(callback: (decision: Decision) => void): Unsubscribe;
  /** Same hash as sim/fingerprint.py once the game is over, else null. */
  fingerprint(): string | null;
  dispose(): void;
}
"""

SCALARS = {int: "number", float: "number", str: "string", bool: "boolean", type(None): "null"}


def ts_type(hint: Any, expand: bool = False) -> str:
    """Return the TypeScript spelling of a type hint used in the contract.

    Named string unions print as their name unless ``expand`` is set.
    """
    if hint == c.GameEvent:
        return "GameEvent"
    for name, alias in c.LITERAL_ALIASES.items():
        if hint == alias and not expand:
            return name
    origin = get_origin(hint)
    if origin is Literal:
        return " | ".join(f'"{value}"' for value in get_args(hint))
    if origin in (Union, types.UnionType):
        parts = [ts_type(arg) for arg in get_args(hint)]
        return " | ".join(sorted(parts, key=lambda part: part == "null"))
    if origin is tuple:
        args = get_args(hint)
        if len(args) == 2 and args[1] is Ellipsis:
            return f"{_array_item(ts_type(args[0]))}[]"
        return "[" + ", ".join(ts_type(arg) for arg in args) + "]"
    if is_dataclass(hint):
        return hint.__name__
    return SCALARS[hint]


def _array_item(spelling: str) -> str:
    return f"({spelling})" if " " in spelling else spelling


def _interface(cls: type, skip: set[str], parent: str | None) -> str:
    hints = get_type_hints(cls)
    lines = [
        f"  {c.camel(f.name)}: {ts_type(hints[f.name])};"
        for f in fields(cls)
        if f.name not in skip
    ]
    extends = f" extends {parent}" if parent else ""
    return f"export interface {cls.__name__}{extends} {{\n" + "\n".join(lines) + "\n}\n"


def render_types() -> str:
    """Return the full text of ``web/src/contract/types.ts``."""
    aliases = [
        f"export type {name} = {ts_type(alias, expand=True)};\n"
        for name, alias in c.LITERAL_ALIASES.items()
    ]
    base_fields = {f.name for f in fields(c.EventBase)}
    events = [_interface(c.EventBase, set(), None)]
    events += [_interface(cls, base_fields, "EventBase") for cls in c.EVENT_TYPES]
    union = "export type GameEvent =\n" + "\n".join(
        f"  | {cls.__name__}" for cls in c.EVENT_TYPES
    ) + ";\n"
    values = [_interface(cls, set(), None) for cls in c.VALUE_TYPES]
    parts = [HEADER, *aliases, *values, *events, union, SESSION_INTERFACE]
    return "\n".join(parts)
